$files = @(); Get-ChildItem app -Recurse -File -Filter "*.php" | Where-Object { $_.LastWriteTime.ToString("yyyy-MM-dd") -eq "2026-08-06" } | ForEach-Object { $files += $_.FullName }; Write-Host "Files: $($files.Count)"; $count = 0; foreach ($f in $files) { $content = Get-Content $f -Raw; $original = $content; $content = $content.Replace("use Filament\Schemas\Schema;", "use Filament\Forms\Form;"); $content = $content.Replace("use Filament\Schemas\Components\Section;", "use Filament\Forms\Components\Section;"); $content = $content.Replace("use Filament\Schemas\Components\Grid;", "use Filament\Forms\Components\Grid;"); $content = $content.Replace("use Filament\Schemas\Components\Fieldset;", "use Filament\Forms\Components\Fieldset;"); $content = $content.Replace("use Filament\Schemas\Components\Tabs;", "use Filament\Forms\Components\Tabs;"); $content = $content.Replace("use Filament\Schemas\Components\Wizard;", "use Filament\Forms\Components\Wizard;"); $content = $content.Replace("use Filament\Schemas\Components\Repeater;", "use Filament\Forms\Components\Repeater;"); $content = $content.Replace("function form(Schema $schema): Schema", "function form(Form $form): Form"); $content = $content.Replace("->components([", "->schema(["); if ($content -ne $original) { Set-Content $f -Value $content; $count++ } }; Write-Host "Reverted: $count"
